  uniforms.set('col1', hex2rgb(P.color1));  // '#492d7b' -> [0.286, 0.176, 0.482]
  uniforms.set('col2', hex2rgb(P.color2));

  // ... all other uniforms ...

  uniforms.upload(device);  // write buffer to GPU
